CREATE TABLE customer_note (
    note_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id smallint NOT NULL REFERENCES customer(customer_id),
    note_text text NOT NULL
);

ALTER TABLE customer_note ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();

DROP TABLE customer_note;

CREATE TEMP TABLE customer_note AS
SELECT customer_id, 'Preferred contact: email'::text AS note_text
FROM customer
WHERE customer_id = 1;

INSERT INTO customer_note (customer_id, note_text)
SELECT customer_id, 'Preferred contact: phone'
FROM customer
WHERE customer_id = 2;

UPDATE customer_note
SET note_text = 'Preferred contact: SMS'
WHERE customer_id = 1;

DELETE FROM customer_note
WHERE customer_id = 2;

SELECT c.customer_id, c.first_name, a.address
FROM customer AS c
INNER JOIN address AS a ON a.address_id = c.address_id;

SELECT c.customer_id, r.rental_id
FROM customer AS c
LEFT JOIN rental AS r ON r.customer_id = c.customer_id;

SELECT c.customer_id, r.rental_id
FROM customer AS c
RIGHT JOIN rental AS r ON r.customer_id = c.customer_id;

SELECT f.title, cat.name AS category
FROM film AS f
JOIN film_category AS fc ON fc.film_id = f.film_id
JOIN category AS cat ON cat.category_id = fc.category_id;

SELECT s1.store_id AS store_a, s2.store_id AS store_b
FROM store AS s1
CROSS JOIN store AS s2
WHERE s1.store_id < s2.store_id;

SELECT c.customer_id
FROM customer AS c
WHERE EXISTS (
    SELECT 1 FROM rental AS r WHERE r.customer_id = c.customer_id
);

SELECT first_name FROM customer
UNION
SELECT first_name FROM staff;

SELECT customer_id FROM customer
INTERSECT
SELECT customer_id FROM rental;

SELECT customer_id FROM customer
EXCEPT
SELECT customer_id FROM rental;

CREATE VIEW customer_payment_summary AS
SELECT customer_id, count(*) AS payment_count, sum(amount) AS total_paid
FROM payment
GROUP BY customer_id;

SELECT *
FROM customer_payment_summary
ORDER BY total_paid DESC;

DROP VIEW customer_payment_summary;

CREATE TEMP TABLE recent_rentals AS
SELECT rental_id, customer_id, rental_date
FROM rental
WHERE rental_date >= date '2005-07-01';

SELECT count(*)
FROM recent_rentals;

CREATE PROCEDURE validate_customer(p_customer_id smallint)
LANGUAGE plpgsql
AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM customer WHERE customer_id = p_customer_id) THEN
        RAISE EXCEPTION 'Customer % does not exist', p_customer_id;
    END IF;
END;
$$;

CALL validate_customer(1);

DROP PROCEDURE validate_customer(smallint);

CREATE FUNCTION set_customer_last_update()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.last_update := now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER customer_set_last_update
BEFORE UPDATE ON customer
FOR EACH ROW EXECUTE FUNCTION set_customer_last_update();

DROP TRIGGER customer_set_last_update ON customer;
DROP FUNCTION set_customer_last_update();

CREATE INDEX idx_payment_customer_date
ON payment (customer_id, payment_date);

SELECT payment_id, amount
FROM payment
WHERE customer_id = 1
  AND payment_date >= timestamp '2005-06-01';

DROP INDEX idx_payment_customer_date;
